def get_common_install_dirs():
    """遍历所有盘符的常规安装位置"""
    dirs = []
    try:
        for letter in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            root = letter + ':\\'
            if os.path.exists(root):
                dirs.append(root)
                for sub in ('Program Files', 'Program Files (x86)'):
                    p = os.path.join(root, sub)
                    if os.path.exists(p):
                        dirs.append(p)
    except Exception:
        pass
    dirs.sort(key=lambda d: 0 if d.lower().startswith('c:\\') else 1)
    return dirs
@functools.lru_cache(maxsize=1024)

def get_short_path(path):
    """仅把路径中含空格的段转为短路径名，其余保留长路径"""
    if sys.platform != 'win32' or not path:
        return path
    path = os.path.normpath(path)
    if ' ' not in path:
        return path
    try:
        GetShortPathName = ctypes.windll.kernel32.GetShortPathNameW
        parts = path.split(os.sep)
        result_parts = []
        current = ''
        for i, part in enumerate(parts):
            if i == 0:
                current = part
                result_parts.append(part)
                continue
            # 手动拼接，避免 os.path.join('D:', 'foo') -> 'D:foo'
            if current.endswith(':'):
                current = current + '\\' + part
            else:
                current = current + os.sep + part
            if ' ' in part:
                buf_len = GetShortPathName(current, None, 0)
                if buf_len == 0:
                    result_parts.append(part)
                else:
                    buf = ctypes.create_unicode_buffer(buf_len)
                    GetShortPathName(current, buf, buf_len)
                    short_part = os.path.basename(buf.value)
                    result_parts.append(short_part)
            else:
                result_parts.append(part)
        return os.sep.join(result_parts)
    except Exception:
        return path

def quote_if_space(path):
    """路径含空格时加双引号，否则原样返回"""
    if not path:
        return path
    if ' ' in path and not (path.startswith('"') and path.endswith('"')):
        return f'"{path}"'
    return path

def get_cache_dir():
    """获取可写的缓存目录"""
    exe_dir = get_exe_directory()
    if os.access(exe_dir, os.W_OK):
        return exe_dir
    fallback = os.path.join(tempfile.gettempdir(), "PyPackTool")
    os.makedirs(fallback, exist_ok=True)
    return fallback

def load_dep_map():
    """加载依赖映射表"""
    global DEPENDENCY_MAP
    if os.path.exists(DEP_MAP_FILE):
        try:
            with open(DEP_MAP_FILE, 'r', encoding='utf-8-sig') as f:
                content = f.read()
            new_map = {}
            for line in content.split('\n'):
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    key, val = line.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    try:
                        deps = ast.literal_eval(val)
                        if isinstance(deps, list):
                            new_map[key] = deps
                    except:
                        deps = re.findall(r'"([^"]+)"', val)
                        if deps:
                            new_map[key] = deps
            if new_map:
                # ===== 合并而非替换: 内置默认(含 ttkbootstrap 等)保留, toml 只补充/覆盖已有键 =====
                _merged = dict(DEPENDENCY_MAP)
                _merged.update(new_map)
                DEPENDENCY_MAP = _merged
                return
        except Exception as e:
            pass
    # ===== toml 不存在时使用内置默认, 不自动生成文件(用户保存时才会写) =====

def load_cache():
    """加载缓存 - 优先内存"""
    global _memory_cache
    if _memory_cache is not None:
        return _memory_cache
    try:
        if os.path.exists(CACHE_FILE):
            with open(CACHE_FILE, 'r', encoding='utf-8-sig') as f:
                _memory_cache = json.load(f)
                return _memory_cache
    except:
        pass
    _memory_cache = {}
    return _memory_cache

def save_cache(cache):
    """保存缓存到文件并更新内存"""
    global _memory_cache
    _memory_cache = cache
    try:
        with open(CACHE_FILE, 'w', encoding='utf-8-sig') as f:
            json.dump(cache, f, ensure_ascii=False, indent=2)
    except:
        pass

def now_str():
    """返回当前时间的字符串格式 HH:MM:SS.mmm"""
    now = datetime.datetime.now()
    return now.strftime("%H:%M:%S") + f".{now.microsecond//1000:03d}"

def is_if_main(node):
    """判断 AST 节点是否为 if __name__ == '__main__':"""
    return (isinstance(node, ast.If) and isinstance(node.test, ast.Compare)
            and isinstance(node.test.left, ast.Name)
            and node.test.left.id == '__name__')

def scan_imports_from_source(source, on_parse_error=None):
    """扫描源码中的 import，返回 (imports:set, uses_tkinter:bool)；AST 失败时降级为正则解析"""
    imports = set()
    uses_tkinter = False
    try:
        tree = ast.parse(source)
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    mod = alias.name.split('.')[0]
                    if mod == 'tkinter':
                        uses_tkinter = True
                        imports.add('tk')
                    elif mod == 'tk':
                        imports.add('tk')
                    elif mod not in STANDARD_LIBS:
                        imports.add(mod)
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    mod = node.module.split('.')[0]
                    if mod == 'tkinter':
                        uses_tkinter = True
                        imports.add('tk')
                    elif mod == 'tk':
                        imports.add('tk')
                    elif mod not in STANDARD_LIBS:
                        imports.add(mod)
    except Exception as e:
        if on_parse_error:
            on_parse_error(e)
        for line in source.split('\n'):
            line = line.strip()
            if line.startswith('import ') or line.startswith('from '):
                if 'tkinter' in line:
                    uses_tkinter = True
                    imports.add('tk')
                else:
                    match = re.match(r'(?:from\s+(\S+)\s+import|import\s+(\S+))', line)
                    if match:
                        mod = match.group(1) or match.group(2)
                        if mod:
                            mod = mod.split('.')[0]
                            if mod not in STANDARD_LIBS:
                                imports.add(mod)
    return imports, uses_tkinter
_PIP_INSTALL_LOCK = threading.Lock()

def pip_install(python_exe, package, env=None, timeout=300, quiet=False):
    """安装包：多镜像自动切换.返回: (success, result)"""
    with _PIP_INSTALL_LOCK:
        return _pip_install_locked(python_exe, package, env=env, timeout=timeout, quiet=quiet)

def _pip_install_locked(python_exe, package, env=None, timeout=300, quiet=False):
    """（锁内执行）实际安装逻辑"""
    global MIRROR
    if not python_exe or not os.path.exists(python_exe):
        return False, None
    if env is None:
        env = {'PATH': os.environ.get('PATH', '')}
        if sys.platform == 'win32':
            env['SYSTEMROOT'] = os.environ.get('SYSTEMROOT', '')
            env['COMSPEC'] = os.environ.get('COMSPEC', '')
    env.setdefault('PYTHONUTF8', '1')
    env.setdefault('PYTHONIOENCODING', 'utf-8')
    startupinfo = get_startupinfo()

    def _run(args, t=timeout):
        return subprocess.run(
            args,
            capture_output=True, text=True, encoding='utf-8', errors='replace',
            env=env, timeout=t, startupinfo=startupinfo
        )
    try:
        probe = _run([python_exe, '-m', 'pip', '--version'], t=10)
        if probe.returncode != 0:
            _run([python_exe, '-m', 'ensurepip', '--upgrade', '--default-pip'], t=120)
    except Exception:
        pass
    cmd = [python_exe, '-m', 'pip', 'install', package]
    if quiet:
        cmd.append('-q')
    cmd += ['--no-warn-script-location', '--disable-pip-version-check',
            '--retries', '1', '--timeout', '10']
    last_error = None
    # ===== 依次尝试各镜像，最后官方源兜底 =====
    _cfg_pips = load_pypack_config().get('pip_mirrors', [])
    _mirror_list = list(MIRRORS)
    for _m in _cfg_pips:
        if _m and _m not in _mirror_list:
            _mirror_list.append(_m)
    for mirror in _mirror_list + [None]:
        try:
            if mirror is None:
                cmd_with_mirror = list(cmd)
            else:
                cmd_with_mirror = cmd + ['-i', mirror]
            result = _run(cmd_with_mirror, t=min(timeout, 120))
            if result.returncode == 0:
                MIRROR = mirror or MIRROR
                # ===== 安装 pywin32 后自动激活 =====
                if package.lower() == 'pywin32' and sys.platform == 'win32':
                    try:
                        _run([python_exe, '-c',
                              'import pywin32_postinstall; pywin32_postinstall.install()'], t=15)
                    except Exception:
                        pass
                return True, result
            last_error = (result.stderr or result.stdout or '').strip()[-300:]
        except subprocess.TimeoutExpired:
            last_error = f"安装超时({timeout}s)"
            continue
        except Exception as e:
            last_error = str(e)
            continue
    if last_error:
        try:
            class _PipFail:
                returncode = 1
                stderr = last_error
                stdout = ''
            return False, _PipFail()
        except Exception:
            pass
    return False, None
# 升级参数的常见简写（用户在依赖管理里输入的），统一规整成 pip 标准 --upgrade
_UPGRADE_SHORTHANDS = ('-u', '-U', '--upgrade', '--up', '--upg')
import re as _re
_UPGRADE_TOKEN_RE = _re.compile(r'(?<![\w\-/])(?:-u|-U|--upgrade|--up|--upg)(?![\w\-/])')

def normalize_pip_upgrade_flags(args_text):
    """把用户输入的升级简写(-u/-U/--up/--upg/--upgrade)规整成 pip 标准 --upgrade。
    其余参数(包名、==版本号、-r requirements.txt 等)保持原样，不会被改动。
    这样用户不必死记 --upgrade，输入 -u / -U 等也能正确触发升级。
    """
    if not args_text:
        return args_text
    return _UPGRADE_TOKEN_RE.sub('--upgrade', args_text)

def pip_install_with_args(python_exe, args_text, env=None, timeout=300, extra_args=None):
    """安装/升级依赖，）。返回: (success, result)"""
    import shlex
    args = shlex.split(args_text, posix=False)
    if extra_args:
        args = args + list(extra_args)
    if not args:
        return False, None
    with _PIP_INSTALL_LOCK:
        if not python_exe or not os.path.exists(python_exe):
            return False, None
        if env is None:
            env = {'PATH': os.environ.get('PATH', '')}
            if sys.platform == 'win32':
                env['SYSTEMROOT'] = os.environ.get('SYSTEMROOT', '')
                env['COMSPEC'] = os.environ.get('COMSPEC', '')
        env.setdefault('PYTHONUTF8', '1')
        env.setdefault('PYTHONIOENCODING', 'utf-8')
        startupinfo = get_startupinfo()
        def _run(cmd, t=timeout):
            return subprocess.run(
                cmd, capture_output=True, text=True, encoding='utf-8', errors='replace',
                env=env, timeout=t, startupinfo=startupinfo
            )
        cmd = [python_exe, '-m', 'pip', 'install'] + args
        cmd += ['--no-warn-script-location', '--disable-pip-version-check',
                '--retries', '1', '--timeout', '10']
        last_error = None
        for mirror in list(MIRRORS) + [None]:
            try:
                cmd_with_mirror = list(cmd) if mirror is None else cmd + ['-i', mirror]
                result = _run(cmd_with_mirror, t=min(timeout, 120))
                if result.returncode == 0:
                    return True, result
                last_error = (result.stderr or result.stdout or '').strip()[-300:]
            except subprocess.TimeoutExpired:
                last_error = f"安装超时({timeout}s)"
                continue
            except Exception as e:
                last_error = str(e)
                continue
        if last_error:
            try:
                class _PipFail:
                    returncode = 1
                    stderr = last_error
                    stdout = ''
                return False, _PipFail()
            except Exception:
                pass
        return False, None
DEP_MAP_FILE = os.path.join(get_exe_directory(), ".dep_map.toml")
# ===== 全局内存缓存 =====
_memory_cache = None

class PythonInstallWorker(QThread):
    """后台静默安装 Python """
    finished_signal = pyqtSignal(bool, str)
    def __init__(self):
        super().__init__()
        self._cancel = False
        self._progress = 0

    def cancel(self):
        self._cancel = True

    def run(self):
        try:
            version = "3.12.10"
            temp_dir = tempfile.gettempdir()
            has_python, version_str = check_python_installed()
            if has_python:
                self.finished_signal.emit(True, f"Python {version_str} 已安装")
                return
            if sys.platform == 'win32':
                filename = f"python-{version}-amd64.exe"
                _inst_cfg = with_backup_sources('installer_mirrors', [
                    "https://www.python.org/ftp/python/{ver}/python-{ver}-amd64.exe",
                    "https://mirrors.tuna.tsinghua.edu.cn/python/{ver}/python-{ver}-amd64.exe",
                    "https://mirrors.aliyun.com/python/{ver}/python-{ver}-amd64.exe",
                    "https://mirrors.ustc.edu.cn/python/{ver}/python-{ver}-amd64.exe",
                ])
                mirrors = [m.format(ver=version) for m in _inst_cfg]
            elif sys.platform == 'darwin':
                filename = f"python-{version}-macos11.pkg"
                mirrors = [
                    f"https://www.python.org/ftp/python/{version}/python-{version}-macos11.pkg",
                    f"https://mirrors.tuna.tsinghua.edu.cn/python/{version}/python-{version}-macos11.pkg",
                ]
            else:
                self.finished_signal.emit(False, "Linux请使用包管理器安装Python")
                return
            installer_path = os.path.join(temp_dir, filename)
            downloaded = False
            last_error = ""
            for i, url in enumerate(mirrors):
                if self._cancel:
                    self.finished_signal.emit(False, "已取消")
                    return
                try:
                    self.finished_signal.emit(False, f"下载中... 尝试镜像 {i+1}/{len(mirrors)}")
                    if _curl_download(url, installer_path, 60):
                        file_size = os.path.getsize(installer_path)
                        if file_size > 5 * 1024 * 1024:
                            downloaded = True
                            self.finished_signal.emit(False, f"下载完成 ({file_size // 1024 // 1024}MB)")
                            break
                        else:
                            last_error = f"文件太小 ({file_size} bytes)"
                    else:
                        last_error = "curl 下载失败"
                except Exception as e:
                    last_error = str(e)
                    continue
            if self._cancel:
                self.finished_signal.emit(False, "已取消")
                return
            if not downloaded:
                self.finished_signal.emit(False, f"下载失败: {last_error}")
                return
            self.finished_signal.emit(False, "安装中... 请稍候")
            if sys.platform == 'win32':
                cmd = [
                    installer_path,
                    '/quiet',
                    'InstallAllUsers=1',
                    'PrependPath=1',
                    'Include_doc=0',
                    'Include_tcltk=0',
                    'Include_test=0',
                    'Include_tools=0',
                    'Include_pip=1',
                    'Include_setuptools=1',
                    'Include_symbols=0',
                    'Include_debug=0',
                    'InstallLauncherAllUsers=1',
                ]
            elif sys.platform == 'darwin':
                cmd = ['sudo', 'installer', '-pkg', installer_path, '-target', '/']
            else:
                self.finished_signal.emit(False, "不支持的操作系统")
                return
            process = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
            )
            timeout_count = 0
            while process.poll() is None:
                if self._cancel:
                    process.terminate()
                    self.finished_signal.emit(False, "已取消")
                    return
                timeout_count += 1
                if timeout_count > 600:
                    process.terminate()
                    self.finished_signal.emit(False, "安装超时")
                    return
                if timeout_count % 30 == 0:
                    progress = min(95, 50 + timeout_count // 6)
                    self.finished_signal.emit(False, f"安装中... {progress}%")
                self.msleep(500)
            try:
                os.remove(installer_path)
            except:
                pass
            if process.returncode == 0:
                self.finished_signal.emit(False, "验证安装...")
                time.sleep(3)
                for attempt in range(5):
                    has_python, version_str = check_python_installed()
                    if has_python:
                        self.finished_signal.emit(True, f"Python {version_str} 安装成功！")
                        return
                    time.sleep(2)
                self.finished_signal.emit(False, "安装完成但验证失败，请手动安装")
            else:
                self.finished_signal.emit(False, f"安装失败 (返回码: {process.returncode})")
        except Exception as e:
            self.finished_signal.emit(False, f"错误: {str(e)}")

def check_python_installed():
    """检测系统是否安装了 Python"""
    IS_FROZEN = getattr(sys, 'frozen', False)

    def is_valid_system_python(path):
        if not path or not os.path.exists(path):
            return False
        if IS_FROZEN:
            try:
                if os.path.samefile(path, sys.executable):
                    return False
            except:
                if path.lower() == sys.executable.lower():
                    return False
        path_lower = path.lower()
        if '_mei' in path_lower or 'onefile_' in path_lower or 'nuitka' in path_lower:
            return False
        try:
            if sys.platform == 'win32':
                result = subprocess.run(
                    [path, '--version'],
                    capture_output=True, text=True, timeout=3,
                    creationflags=subprocess.CREATE_NO_WINDOW
                )
            else:
                result = subprocess.run(
                    [path, '--version'],
                    capture_output=True, text=True, timeout=3
                )
            if result.returncode == 0:
                output = result.stdout + result.stderr
                return 'Python' in output
        except:
            pass
        return False

    def get_python_version(path):
        """获取Python版本"""
        try:
            if sys.platform == 'win32':
                result = subprocess.run(
                    [path, '--version'],
                    capture_output=True, text=True, timeout=3,
                    creationflags=subprocess.CREATE_NO_WINDOW
                )
            else:
                result = subprocess.run(
                    [path, '--version'],
                    capture_output=True, text=True, timeout=3
                )
            if result.returncode == 0:
                output = result.stdout.strip() or result.stderr.strip()
                return output
        except:
            pass
        return None
    if sys.platform == 'win32':
        try:
            result = subprocess.run(
                ['py', '--version'],
                capture_output=True, text=True, timeout=3,
                creationflags=subprocess.CREATE_NO_WINDOW
            )
            if result.returncode == 0:
                version = result.stdout.strip() or result.stderr.strip()
                return True, version
        except:
            pass
        try:
            result = subprocess.run(
                ['py', '-c', 'import sys; print(sys.executable)'],
                capture_output=True, text=True, timeout=3,
                creationflags=subprocess.CREATE_NO_WINDOW
            )
            if result.returncode == 0:
                py_path = result.stdout.strip()
                if py_path and is_valid_system_python(py_path):
                    version = get_python_version(py_path)
                    if version:
                        return True, version
        except:
            pass
        try:
            result = subprocess.run(
                ['where', 'python'],
                capture_output=True, text=True, timeout=3,
                creationflags=subprocess.CREATE_NO_WINDOW
            )
            if result.returncode == 0:
                for line in result.stdout.strip().split('\n'):
                    py_path = line.strip()
                    if is_valid_system_python(py_path):
                        version = get_python_version(py_path)
                        if version:
                            return True, version
        except:
            pass
        try:
            import winreg
            for root in [winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE]:
                try:
                    key = winreg.OpenKey(root, r'Software\Python\PythonCore')
                    i = 0
                    while True:
                        try:
                            version_key = winreg.EnumKey(key, i)
                            if version_key.startswith('3.'):
                                try:
                                    install_key = winreg.OpenKey(key, fr'{version_key}\InstallPath')
                                    install_path, _ = winreg.QueryValueEx(install_key, '')
                                    if install_path:
                                        py_path = os.path.join(install_path, 'python.exe')
                                        if os.path.exists(py_path) and is_valid_system_python(py_path):
                                            version = get_python_version(py_path)
                                            if version:
                                                return True, version
                                except:
                                    pass
                            i += 1
                        except WindowsError:
                            break
                except:
                    pass
        except:
            pass
    for cmd in ['python3', 'python']:
        py_path = shutil.which(cmd)
        if py_path and is_valid_system_python(py_path):
            version = get_python_version(py_path)
            if version:
                return True, version
    if sys.platform == 'win32':
        username = os.environ.get('USERNAME', '')
        search_patterns = []
        for _base in get_common_install_dirs():
            search_patterns.append(os.path.join(_base, 'Python3*'))
            search_patterns.append(os.path.join(_base, 'Python3*', 'python.exe'))
        search_patterns.append(os.path.join(os.path.expanduser('~'), 'AppData', 'Local', 'Programs', 'Python', 'Python3*', 'python.exe'))
        for pattern in search_patterns:
            for path in glob.glob(pattern):
                if os.path.isfile(path) and path.endswith('python.exe'):
                    if is_valid_system_python(path):
                        version = get_python_version(path)
                        if version:
                            return True, version
                elif os.path.isdir(path):
                    exe_path = os.path.join(path, 'python.exe')
                    if os.path.exists(exe_path) and is_valid_system_python(exe_path):
                        version = get_python_version(exe_path)
                        if version:
                            return True, version
    elif sys.platform == 'darwin':
        paths_to_check = [
            '/usr/local/bin/python3',
            '/usr/bin/python3',
            '/opt/homebrew/bin/python3',
            '/Library/Frameworks/Python.framework/Versions/3.*/bin/python3',
        ]
        for pattern in paths_to_check:
            for path in glob.glob(pattern):
                if os.path.exists(path) and is_valid_system_python(path):
                    version = get_python_version(path)
                    if version:
                        return True, version
    else:
        paths_to_check = [
            '/usr/bin/python3',
            '/usr/local/bin/python3',
            '/usr/bin/python',
            '/opt/python3/bin/python3',
        ]
        for path in paths_to_check:
            if os.path.exists(path) and is_valid_system_python(path):
                version = get_python_version(path)
                if version:
                    return True, version
    return False, None

def ensure_python_on_startup():
    """启动时检测 Python"""
    if not getattr(sys, 'frozen', False):
        return True
    has_python, version = check_python_installed()
    if has_python:
        print(f"[Main] 检测到系统Python: {version}")
        return True
    print("[Main] 未检测到系统Python，后台静默安装...")
    if sys.platform == "win32":
        try:
            if not ctypes.windll.shell32.IsUserAnAdmin():
                print("[Main] 警告: 非管理员模式，安装可能失败")
        except:
            pass
    from PyQt6.QtWidgets import QApplication
    app = QApplication.instance()
    if app is None:
        app = QApplication(sys.argv)
        app.setStyle('Fusion')
    from PyQt6.QtWidgets import QWidget, QVBoxLayout, QHBoxLayout, QLabel, QProgressBar, QPushButton
    from PyQt6.QtCore import QTimer, Qt
    tip_widget = QWidget(None, Qt.WindowType.Window | Qt.WindowType.WindowStaysOnTopHint)
    tip_widget.setWindowTitle("安装 Python")
    tip_widget.setFixedSize(380, 140)
    tip_widget.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
    layout = QVBoxLayout(tip_widget)
    layout.setSpacing(8)
    status_label = QLabel("⏳ 正在后台静默安装 Python 3.12.10...")
    status_label.setStyleSheet("font-size: 13px; font-weight: bold;")
    status_label.setWordWrap(True)
    layout.addWidget(status_label)
    progress_bar = QProgressBar()
    progress_bar.setRange(0, 100)
    progress_bar.setValue(0)
    progress_bar.setTextVisible(True)
    layout.addWidget(progress_bar)
    btn_layout = QHBoxLayout()
    btn_layout.addStretch()
    hide_btn = QPushButton("最小化到托盘")
    hide_btn.setFixedWidth(100)
    btn_layout.addWidget(hide_btn)
    cancel_btn = QPushButton("取消")
    cancel_btn.setFixedWidth(60)
    btn_layout.addWidget(cancel_btn)
    layout.addLayout(btn_layout)
    tip_widget.show()
    worker = PythonInstallWorker()
    install_success = False

    def on_progress(success, msg):
        nonlocal install_success
        if success:
            install_success = True
            status_label.setText("✅ " + msg)
            progress_bar.setValue(100)
            hide_btn.setEnabled(False)
            cancel_btn.setEnabled(False)
            cancel_btn.setText("重启")
            cancel_btn.clicked.connect(lambda: restart_app())
            QTimer.singleShot(3000, tip_widget.close)
        else:
            if "下载" in msg or "安装" in msg:
                status_label.setText("⏳ " + msg)
                import re
                match = re.search(r'(\d+)%', msg)
                if match:
                    progress_bar.setValue(int(match.group(1)))
            else:
                status_label.setText("⏳ " + msg)
                cancel_btn.setText("关闭")
                cancel_btn.clicked.connect(tip_widget.close)

    def on_hide():
        """最小化到托盘或隐藏窗口"""
        tip_widget.hide()
        print("[Main] Python安装已在后台继续...")

    def on_cancel():
        """取消安装"""
        if worker.isRunning():
            worker.cancel()
            worker.wait()
        tip_widget.close()

    def restart_app():
        """重启程序"""
        tip_widget.close()
        subprocess.Popen([sys.executable] + sys.argv)
        sys.exit(0)
    worker.finished_signal.connect(on_progress)
    hide_btn.clicked.connect(on_hide)
    cancel_btn.clicked.connect(on_cancel)
    worker.start()
    return True

def patch_subprocess_hide_window():
    """ 所有 subprocess 调用默认隐藏 cmd 窗口（Windows）"""
    if sys.platform == "win32":
        _orig_run = subprocess.run
        _orig_popen = subprocess.Popen
        _orig_call = subprocess.call
        _orig_check_call = subprocess.check_call
        _orig_check_output = subprocess.check_output
        CREATE_NO_WINDOW = 0x08000000
        def _patched_run(*args, **kwargs):
            if 'creationflags' not in kwargs:
                kwargs['creationflags'] = CREATE_NO_WINDOW
            return _orig_run(*args, **kwargs)
        def _patched_popen(*args, **kwargs):
            if 'creationflags' not in kwargs:
                kwargs['creationflags'] = CREATE_NO_WINDOW
            return _orig_popen(*args, **kwargs)
        def _patched_call(*args, **kwargs):
            if 'creationflags' not in kwargs:
                kwargs['creationflags'] = CREATE_NO_WINDOW
            return _orig_call(*args, **kwargs)
        def _patched_check_call(*args, **kwargs):
            if 'creationflags' not in kwargs:
                kwargs['creationflags'] = CREATE_NO_WINDOW
            return _orig_check_call(*args, **kwargs)
        def _patched_check_output(*args, **kwargs):
            if 'creationflags' not in kwargs:
                kwargs['creationflags'] = CREATE_NO_WINDOW
            return _orig_check_output(*args, **kwargs)
        subprocess.run = _patched_run
        subprocess.Popen = _patched_popen
        subprocess.call = _patched_call
        subprocess.check_call = _patched_check_call
        subprocess.check_output = _patched_check_output

def show_msg(parent, title, text, timeout=0, buttons='ok'):
    """
    通用消息框（PyQt6）调用示例:
        show_msg(self, "提示", "操作完成")
        show_msg(self, "完成", "打包成功！", 3)
        if show_msg(self, "确认", "是否继续？", 3, 'yes_no'):
            self.do_continue()   # 点击"是" 或 超时 → 执行
        else:
            print("取消")        # 点击"否" → 跳过
        if show_msg(self, "提示", "确定要删除吗？", 5, 'ok_cancel'):
            self.do_delete()     # 点击"确定" 或 超时 → 执行
        else:
            print("取消删除")
        show_msg(None, "后台任务", "完成！", 2)
        QMessageBox.critical(self, "错误", "打包失败！")
    """
    from PyQt6.QtWidgets import QMessageBox
    from PyQt6.QtCore import QTimer
    btn_map = {
        'ok': QMessageBox.StandardButton.Ok,
        'ok_cancel': QMessageBox.StandardButton.Ok | QMessageBox.StandardButton.Cancel,
        'yes_no': QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
    }
    msg = QMessageBox(parent)
    msg.setWindowTitle(title)
    msg.setText(text)
    msg.setIcon(QMessageBox.Icon.Information)
    msg.setStandardButtons(btn_map.get(buttons, QMessageBox.StandardButton.Ok))
    if timeout > 0:
        remaining = timeout
        msg.setText(f"{text}\n\n⏱️ {remaining}秒后自动...")
        timer = QTimer(msg)
        def update():
            nonlocal remaining
            remaining -= 1
            if remaining > 0:
                msg.setText(f"{text}\n\n⏱️ {remaining}秒后自动...")
            else:
                timer.stop()
        timer.timeout.connect(update)
        timer.start(1000)
        QTimer.singleShot(timeout * 1000, msg.accept)
    result = msg.exec()
    if buttons == 'ok':
        return True
    elif buttons == 'ok_cancel':
        return result == QMessageBox.StandardButton.Ok
    elif buttons == 'yes_no':
        return result == QMessageBox.StandardButton.Yes
    return False

class AnalyzeUsedThread(QThread):
    """后台执行 _analyze_used 的纯计算部分（无UI操作）"""
    finished = pyqtSignal(list, list, list, bool)  # result, real_imports, extra_deps, uses_tkinter
    error = pyqtSignal(str)
    def __init__(self, script_path):
        super().__init__()
        self.script_path = script_path

    def run(self):
        try:
            with open(self.script_path, 'r', encoding='utf-8-sig', errors='replace') as f:
                source = f.read()
        except Exception as e:
            self.error.emit(str(e))
            self.finished.emit([], [], [], False)
            return
        try:
            imports = set()
            uses_tkinter = False
            # ===== 1. AST 解析所有 import =====
            imports, uses_tkinter = scan_imports_from_source(source)
            # ===== 2. 过滤（使用全局 FILTER_MODULES） =====
            result = []
            for mod in sorted(imports):
                mod_clean = mod.split('==')[0].split(' ')[0].strip()
                if mod_clean and mod_clean not in FILTER_MODULES:
                    if mod_clean not in result:
                        result.append(mod_clean)
            # ===== 3. 确保 tk 在结果中 =====
            if uses_tkinter and 'tk' not in result:
                result.append('tk')
            # ===== 4. 自动补充隐式依赖（使用全局 DEPENDENCY_MAP, 大小写不敏感比对） =====
            real_imports = result.copy()
            extra_deps = set()
            _result_lower = [str(r).lower() for r in result]
            for mod, deps in DEPENDENCY_MAP.items():
                if str(mod).lower() in _result_lower:
                    for dep in deps:
                        if str(dep).lower() not in _result_lower:
                            result.append(dep)
                            _result_lower.append(str(dep).lower())
                            extra_deps.add(dep)
            self.finished.emit(result, real_imports, list(extra_deps), uses_tkinter)
        except Exception as e:
            import traceback
            self.error.emit("分析线程异常: %s" % traceback.format_exc())
            self.finished.emit([], [], [], False)

class PythonHighlighter(QSyntaxHighlighter):
    """Python 语法高亮器"""
    def __init__(self, parent=None):
        super().__init__(parent)
        keyword_format = QTextCharFormat()
        keyword_format.setForeground(QColor("#569CD6"))
        keyword_format.setFontWeight(QFont.Weight.Bold)
        keywords = [
            'def', 'class', 'import', 'from', 'return', 'if', 'elif', 'else', 'for',
            'while', 'try', 'except', 'finally', 'with', 'as', 'pass', 'break',
            'continue', 'lambda', 'yield', 'assert', 'raise', 'del', 'global',
            'nonlocal', 'True', 'False', 'None', 'and', 'or', 'not', 'is', 'in',
            'async', 'await', '__init__', '__name__', '__main__', '__file__'
        ]
        self.rules = []
        for kw in keywords:
            pattern = QRegularExpression(r'\b' + kw + r'\b')
            self.rules.append((pattern, keyword_format))
        string_format = QTextCharFormat()
        string_format.setForeground(QColor("#CE9178"))
        self.rules.append((QRegularExpression(r'"[^"\\]*(\\.[^"\\]*)*"'), string_format))
        self.rules.append((QRegularExpression(r"'[^'\\]*(\\.[^'\\]*)*'"), string_format))
        comment_format = QTextCharFormat()
        comment_format.setForeground(QColor("#6A9955"))
        self.rules.append((QRegularExpression(r'#.*'), comment_format))
        number_format = QTextCharFormat()
        number_format.setForeground(QColor("#B5CEA8"))
        self.rules.append((QRegularExpression(r'\b[0-9]+\b'), number_format))

    def highlightBlock(self, text):
        for pattern, fmt in self.rules:
            iterator = pattern.globalMatch(text)
            while iterator.hasNext():
                match = iterator.next()
                self.setFormat(match.capturedStart(), match.capturedLength(), fmt)

